const step = $json.step;
const firstName = ($json.full_name || '').split(' ')[0];
const company = $json.company || '';

const templates = [
  { // step 0
    subject: `${company} için 1 fikir`,
    body: `Merhaba ${firstName},\n\n${company}'nin LinkedIn'ini bakıyordum. [X konusu] için [basit faydayı] ekleyebiliriz — müşterilerimiz ortalama [Y metrik] iyileşme görüyor.\n\nBir demo görmek ister misin? 15 dakika yeter.\n\n— [Senin adın]`
  },
  { // step 1
    subject: `${company} — hâlâ mantıklı mı`,
    body: `Merhaba ${firstName},\n\nGeçen mesajım gözden kaçmıştır. Kısaca: ${company} için [çözülen dert]'i otomatikleştiriyoruz.\n\n3 gün içinde canlı göremezsem, tekrar rahatsız etmem.\n\n— [Senin adın]`
  },
  { // step 2
    subject: `Örnek: nasıl çalışıyor`,
    body: `Merhaba ${firstName},\n\nSöz verdim daha sade anlatayım — bir müşterimiz [X yaptı], 2 haftada [Y sonuç] aldı. Loom'da 2 dakikalık video: [LINK]\n\nBakıp ne düşündüğünü yazarsan yeter.`
  },
  { // step 3
    subject: `Son mesaj`,
    body: `${firstName}, son mesajım.\n\nİlgini çekmiyorsa tamamen anlayışla karşılarım. Ama şu an zaman değilse 3 ay sonra denesem mi, yoksa hiç yazmasam mı?`
  }
];

return [{
  json: {
    ...$json,
    subject: templates[step].subject,
    bodyText: templates[step].body,
    nextStep: step + 1
  }
}];
